package android.app;import android.os.*;import android.content.*;public class PendingIntent implements Parcelable {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2,FLAG_ONE_SHOT=4;public Intent intent;public boolean cancelled,failSends;public int sends,flags;public static PendingIntent getService(Context c,int code,Intent i,int f){PendingIntent p=new PendingIntent();p.intent=new Intent(i);p.flags=f;return p;}public static PendingIntent getForegroundService(Context c,int code,Intent i,int f){return getService(c,code,i,f);}public static class CanceledException extends Exception{}public void send()throws CanceledException{if(cancelled)throw new CanceledException();sends++;if(failSends)throw new IllegalStateException("injected ticket transport failure");if((flags&FLAG_ONE_SHOT)!=0)cancelled=true;fixture.Env.dispatch(intent);}public void cancel(){cancelled=true;}}